  if(type===20){r(object.color,0,3,8,5);r("#51432f",1,1,2,3);r("#3b3f40",5,0,2,4);r(object.accent,1,4,6,1);r("#d48238",2,5,2,2);r("#303538",5,5,2,2);r("#252728",6,0,1,2)}
